using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Covers the real HTTP boundary with the payment provider: the request we build,
/// the responses we must be able to read back, and the provider's outright refusal (402).
/// A stub <see cref="HttpMessageHandler"/> stands in for the provider so we exercise the
/// actual <see cref="HttpClient"/> pipeline (serialization, headers, status handling)
/// without a real network call.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_contract_expects()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, new { status = "approved" });
        var sut = CreateGateway(handler);

        await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.LastRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.LastRequest.RequestUri!.PathAndQuery);
        var sentBody = JsonSerializer.Deserialize<JsonElement>(handler.LastRequestBody!);
        Assert.Equal("ORD-7", sentBody.GetProperty("reference").GetString());
        Assert.Equal(12.50m, sentBody.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", sentBody.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task Reads_back_an_approved_decision()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, new { status = "approved" });
        var sut = CreateGateway(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task Reads_back_a_declined_decision()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, new { status = "declined" });
        var sut = CreateGateway(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Treats_the_providers_outright_refusal_as_declined()
    {
        // 402 Payment Required is the provider's way of refusing the request outright,
        // with no usable JSON body.
        var handler = new StubHttpMessageHandler(HttpStatusCode.PaymentRequired, body: null);
        var sut = CreateGateway(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Treats_an_unrecognised_status_value_as_declined()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, new { status = "pending" });
        var sut = CreateGateway(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Surfaces_provider_server_errors_instead_of_hiding_them()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.InternalServerError, body: null);
        var sut = CreateGateway(handler);

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None));
    }

    private static PaymentAuthorization.Infrastructure.HttpPaymentGateway CreateGateway(HttpMessageHandler handler)
    {
        var client = new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") };
        return new PaymentAuthorization.Infrastructure.HttpPaymentGateway(client);
    }

    private sealed class StubHttpMessageHandler(HttpStatusCode statusCode, object? body) : HttpMessageHandler
    {
        public HttpRequestMessage? LastRequest { get; private set; }
        public string? LastRequestBody { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            LastRequest = request;
            LastRequestBody = request.Content is null
                ? null
                : await request.Content.ReadAsStringAsync(cancellationToken);

            var response = new HttpResponseMessage(statusCode);
            if (body is not null) response.Content = JsonContent.Create(body);
            return response;
        }
    }
}

